export function togglePause(world) {
  if (world.phase === PHASE.RUNNING) {
    world.phase = PHASE.PAUSED;
    world.events.push({ type: 'pause' });
  } else if (world.phase === PHASE.PAUSED) {
    world.phase = PHASE.RUNNING;
    world.events.push({ type: 'resume' });
  }
  return world.phase;
